func (sh *strictHandler) InstanceGetDiscovery(w http.ResponseWriter, r *http.Request) {
	var request InstanceGetDiscoveryRequestObject

	handler := func(ctx context.Context, w http.ResponseWriter, r *http.Request, request interface{}) (interface{}, error) {
		return sh.ssi.InstanceGetDiscovery(ctx, request.(InstanceGetDiscoveryRequestObject))
	}
	for _, middleware := range sh.middlewares {
		handler = middleware(handler, "InstanceGetDiscovery")
	}

	response, err := handler(r.Context(), w, r, request)

	if err != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, err)
	} else if validResponse, ok := response.(InstanceGetDiscoveryResponseObject); ok {
		if err := validResponse.VisitInstanceGetDiscoveryResponse(w); err != nil {
			sh.options.ResponseErrorHandlerFunc(w, r, err)
		}
	} else if response != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, fmt.Errorf("unexpected response type: %T", response))
	}
}

